package com.queuex.api.controller;
import com.queuex.api.model.AppUser; import com.queuex.api.repo.UserRepository; import com.queuex.api.security.JwtService; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {record Credentials(@Email @NotBlank String email,@Size(min=8) String password){} record Token(String token,String email){} private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Credentials c){if(users.findByEmail(c.email()).isPresent())return ResponseEntity.badRequest().body(Map.of("error","Email already registered"));AppUser u=new AppUser();u.email=c.email().toLowerCase();u.passwordHash=encoder.encode(c.password());users.save(u);return ResponseEntity.ok(new Token(jwt.create(u.email),u.email));}
 @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Credentials c){var u=users.findByEmail(c.email().toLowerCase()).orElse(null);if(u==null||!encoder.matches(c.password(),u.passwordHash))return ResponseEntity.status(401).body(Map.of("error","Invalid credentials"));return ResponseEntity.ok(new Token(jwt.create(u.email),u.email));}
}
